// Content with portions generated by generative AI platform
package org.eclipse.kura.openapi;

import static org.junit.Assert.assertEquals;
import static org.junit.Assert.assertFalse;
import static org.junit.Assert.assertTrue;

import java.nio.file.Files;
import java.nio.file.Path;

import org.junit.Test;

import com.fasterxml.jackson.databind.JsonNode;

import io.swagger.v3.core.util.Json;

public class JwtSecurityContractTest {

    private JsonNode document;
    private JsonNode schemes;
    private JsonNode globalSecurity;
    private JsonNode paths;

    @Test
    public void bearerAuthenticationIsAvailableForProtectedOperations() throws Exception {
        givenGeneratedDocument();

        whenSecurityConfigurationIsRead();

        thenBearerAuthenticationIsDocumented();
    }

    @Test
    public void tokenIssueAndRefreshHaveDistinctSecurityRequirements() throws Exception {
        givenGeneratedDocument();

        whenTokenOperationsAreRead();

        thenRefreshIsPublic();
        thenIssueRejectsBearerAuthentication();
    }

    private void givenGeneratedDocument() throws Exception {
        this.document = Json.mapper()
                .readTree(Files.readString(Path.of(System.getProperty("openapi.directory"), "openapi.json")));
    }

    private void whenSecurityConfigurationIsRead() {
        this.schemes = this.document.path("components").path("securitySchemes");
        this.globalSecurity = this.document.path("security");
    }

    private void whenTokenOperationsAreRead() {
        this.paths = this.document.path("paths");
    }

    private void thenBearerAuthenticationIsDocumented() {
        assertEquals("http", this.schemes.path("bearerAuth").path("type").asText());
        assertEquals("bearer", this.schemes.path("bearerAuth").path("scheme").asText());
        assertEquals("JWT", this.schemes.path("bearerAuth").path("bearerFormat").asText());
        assertTrue(this.globalSecurity.toString(), hasScheme(this.globalSecurity, "bearerAuth"));
    }

    private void thenRefreshIsPublic() {
        final JsonNode security = this.paths.path("/token/jwt/v1/refresh").path("post").path("security");
        assertTrue(security.isArray());
        assertEquals(0, security.size());
    }

    private void thenIssueRejectsBearerAuthentication() {
        final JsonNode security = this.paths.path("/token/jwt/v1/issue").path("post").path("security");
        assertTrue(security.isArray());
        assertFalse(security.isEmpty());
        assertTrue(security.toString(), hasScheme(security, "basicAuth"));
        assertFalse(security.toString(), hasScheme(security, "bearerAuth"));
        assertTrue(security.toString(), hasSessionAuthentication(security));
    }

    private static boolean hasScheme(final JsonNode requirements, final String scheme) {
        for (final JsonNode requirement : requirements) {
            if (requirement.has(scheme)) {
                return true;
            }
        }
        return false;
    }

    private static boolean hasSessionAuthentication(final JsonNode requirements) {
        for (final JsonNode requirement : requirements) {
            if (requirement.has("sessionCookie") && requirement.has("xsrfToken")) {
                return true;
            }
        }
        return false;
    }
}
